  "perm.full_hint": { zh: "全部权限：写文件等自动执行，仅 run_cmd/杀进程等高危仍确认", en: "Full: auto-run most tools; run_cmd/kill still confirm", ja: "フル：高危のみ確認", ru: "Полный: опасное всё ещё спрашивает" },
  "perm.safe": { zh: "安全", en: "Safe", ja: "安全", ru: "Безопасно" },
